const fs = require('fs');

function min(a, b) {
    return a < b ? a : b;
}

function max(a, b) {
    return a > b ? a : b;
}

function lucky(i) {
    return i === 1 ? 0 : lucky(Math.floor(i / 2)) * 10 + (i % 2 === 0 ? 4 : 7);
}

function main() {
    const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
    let l = input[0];
    let r = input[1];

    const aa = new Array(2047);
    let i;
    let x, y, ans;

    aa[0] = 4;
    for (i = 1; i < 2047; i++)
        aa[i] = lucky(i + 1);

    ans = 0;
    for (i = 0; i < 2047; i++) {
        x = max((i - 1 >= 0 ? aa[i - 1] : 0) + 1, l);
        y = min(aa[i], r);
        if (x <= y)
            ans += (y - x + 1) * aa[i];
    }
    console.log(ans.toString());
}

